use verus::prelude::*;

#[requires(m >= 1)]
#[requires((m - 1) as usize < tasks.len())]
#[requires(
    // every task is in the valid range 1..=n
    forall(|i: usize| i < tasks.len() ==> 1 <= tasks[i] && tasks[i] <= n)
)]
#[ensures(|result: i8|
    // result is exactly (last_task − 1)
    result == tasks[(m - 1) as usize] - 1
)]
fn solve(n: i8, m: i8, tasks: Vec<i8>) -> i8 {
    // Access the last task (at index m-1) and subtract 1.
    let last_task = tasks[(m - 1) as usize];
    last_task - 1
}

