        // Single task, e.g. n=2, tasks=[1], final index = 0.
        assert_eq!(solve(2, 1, vec![1]), 0);

        // Final task equal to n, e.g. n=10, tasks=[3,10], index = 9.
        assert_eq!(solve(10, 2, vec![3, 10]), 9);
